import {
  EProtocolOfExchange,
  type IFetchBuildTxParams,
  type ISwapToken,
} from '@onekeyhq/shared/types/swap/types';

type ISwapRequestAccountContext = {
  accountAddress?: string;
  accountId?: string;
  accountNetworkId?: string;
  isAllNetworkFetchAccountTokens?: boolean;
  onlyAccountTokens?: boolean;
};

export function resolveSwapRequestAccountContext({
  isTravelMode,
  ...accountContext
}: ISwapRequestAccountContext & { isTravelMode: boolean }) {
  return isTravelMode
    ? ({} satisfies ISwapRequestAccountContext)
    : accountContext;
}

export function shouldAttachSwapReferralBuildTxParams(
  protocol: EProtocolOfExchange,
) {
  return protocol === EProtocolOfExchange.SWAP;
}

export function buildSwapReferralBuildTxParams(referralInfo?: {
  address: string;
  networkId: string;
  rebateAddress?: string;
}): Pick<
  IFetchBuildTxParams,
  'bindedAccountAddress' | 'bindedNetworkId' | 'rebateAddress'
> {
  if (!referralInfo) {
    return {};
  }
  return {
    bindedAccountAddress: referralInfo.address,
    bindedNetworkId: referralInfo.networkId,
    ...(referralInfo.rebateAddress
      ? { rebateAddress: referralInfo.rebateAddress }
      : {}),
  };
}

export function buildPerpDepositOrderStatusRequestParams(params: {
  networkId: string;
  txId: string;
  isArbUSDCToken: boolean;
  toPerpDepositTokenAddress?: string;
  receivingAddress: string;
  orderId?: string;
}) {
  return {
    networkId: params.networkId,
    txId: params.txId,
    isArbUSDCToken: params.isArbUSDCToken,
    toPerpDepositTokenAddress: params.toPerpDepositTokenAddress,
    receivedAddress: params.receivingAddress,
    ...(params.orderId ? { orderId: params.orderId } : {}),
  };
}

export function buildSwapRequestErrorToastPayload(error?: {
  message?: string;
  requestId?: string;
}) {
  return {
    diagnosticText: error?.requestId
      ? `RequestId: ${error.requestId}`
      : undefined,
    method: 'error' as const,
    requestId: error?.requestId,
    title: error?.message ?? 'Request failed',
  };
}

export function normalizeSwapTokenListCurrency({
  tokens,
  currency,
}: {
  tokens: ISwapToken[];
  currency: string;
}) {
  return tokens.map((token) => {
    if (!token.price && !token.fiatValue) {
      return token;
    }

    return {
      ...token,
      currency,
    };
  });
}

export function mergeSwapTokenLists(tokenLists: ISwapToken[][]) {
  const seen = new Set<string>();
  return tokenLists.flatMap((tokens) =>
    tokens.filter((token) => {
      const key = `${token.networkId}:${token.contractAddress.toLowerCase()}`;
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    }),
  );
}
